#!/usr/bin/env python3
"""Build the Phase 4 manuscript from the preserved Phase 3 canonical source."""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]
source = ROOT / "publication_phase3/manuscript/MURU_MANUSCRIPT_SOURCE.md"
output = ROOT / "publication_phase4/manuscript/MURU_PHASE4_MANUSCRIPT_SOURCE.md"
text = source.read_text(encoding="utf-8")

def replace(old, new, label):
    global text
    if old not in text:
        raise SystemExit(f"Required source passage not found: {label}")
    text = text.replace(old, new)

