# Update citation indices: insert the peer-reviewed ICEBERG primary article at 7.
main, refs = text.split("## References\n", 1)
def shift(m):
    body = m.group(1)
    return "[" + re.sub(r"\d+", lambda n: str(int(n.group()) + (int(n.group()) >= 7)), body) + "]"
main = re.sub(r"\[([0-9]+(?:[,–-][0-9]+)*)\]", shift, main)
lines = []
for line in refs.splitlines():
    m = re.match(r"^(\d+)\.\s+(.*)$", line)
    if m:
        number = int(m.group(1))
        lines.append(f"{number + (number >= 7)}. {m.group(2)}")
    else:
        lines.append(line)
iceberg = ("7. S. Goldman, J. Li, C. W. Coley. Generating molecular fragmentation graphs with autoregressive neural networks. "
           "Analytical Chemistry. Vol. 96, pg. 3419–3428, 2024. https://doi.org/10.1021/acs.analchem.3c04654.")
lines = [iceberg] + lines
lines.sort(key=lambda line: int(re.match(r"^(\d+)\.", line).group(1)) if re.match(r"^(\d+)\.", line) else 999)
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(main.rstrip() + "\n\n## References\n" + "\n".join(lines).strip() + "\n", encoding="utf-8")
abstract = re.search(r"## Abstract\n(.*?)\n\n\*\*Keywords", main, flags=re.S).group(1)
words = re.findall(r"\b[\wμα]+(?:[-’'][\wμα]+)*\b", abstract)
reference_count = len(re.findall(r"^\d+\. ", "\n".join(lines), re.M))
print(f"wrote {output}; references={reference_count}; abstract_words={len(words)}")
